mapper.select:
select g.id, g.user_id, g.google_auth_key, g.create_by, g.create_time, g.update_by, g.update_time, u.user_name, u.nick_name from sys_google g left join sys_user u on g.user_id = u.user_id left join sys_dept d on u.dept_id = d.dept_id where u.del_flag = '0'
and g.user_id = #{userId}
and u.user_name like concat('%', #{userName}, '%')
and date_format(g.create_time,'%Y%m%d') >= date_format(#{params.beginTime},'%Y%m%d')
and date_format(g.create_time,'%Y%m%d') <= date_format(#{params.endTime},'%Y%m%d')
${params.dataScope}

mapper.insert:
insert into sys_google(
    user_id, google_auth_key, create_by, create_time
) values (
    #{userId}, #{googleAuthKey}, #{createBy}, sysdate()
)
